sources.en:
classDiagram
    direction LR
    class Renderer {
        +render(source)
    }
    class NativeRenderer {
        -scene DiagramScene
        +render(source)
    }
    class SVGExporter {
        +export(scene)
    }
    Renderer <|.. NativeRenderer
    NativeRenderer --> SVGExporter : exports

